def factorial(n):
    """
    Compute the factorial of a non‑negative integer n using recursion.

    The function calls itself with decreasing values of n until it reaches the base case (n == 0 or n == 1), at which point it returns 1. Each recursive call multiplies n by the result of factorial(n‑1).

    Time Complexity: O(n²)
    Space Complexity: O(n) due to the recursion stack.
    """
    if n <= 1:
        return 1
    else:
        return n * factorial(n - 1)

def compute_factorial(n):
    """Return the factorial of a non‑negative integer n using recursion.

    Args:
        n (int): A non‑negative integer.
    Returns:
        int: The factorial of n.
    """
    if n == 0:
        return 1
    else:
        return n * compute_factorial(n - 1)

